import hashlib
import hmac
import time
import struct
import os
from functools import lru_cache

# Access control system with role hierarchy
# Roles: 0=guest, 1=user, 2=moderator, 3=admin, 4=superadmin

_SECRET_KEY = os.environ.get('APP_SECRET')
if not _SECRET_KEY:
    raise RuntimeError(
        "APP_SECRET environment variable must be set to a strong, "
        "random secret. Refusing to start with an insecure default key."
    )
SECRET_KEY = _SECRET_KEY
MAX_ROLE_LEVEL = 4
SESSION_TIMEOUT = 3600

class RoleHierarchy:
    """Manages role-based access with numeric privilege levels."""

    def __init__(self):
        self._role_names = {
            0: 'guest', 1: 'user', 2: 'moderator',
            3: 'admin', 4: 'superadmin'
        }
        self._required_levels = {
            '/public': 0,
            '/profile': 1,
            '/moderate': 2,
            '/admin': 3,
            '/system': 4
        }

    def get_required_level(self, resource: str) -> int:
        """Get minimum role level needed for a resource."""
        for prefix, level in self._required_levels.items():
            if resource.startswith(prefix):
                return level
        return 1  # Default requires at least user

    def role_name(self, level: int) -> str:
        return self._role_names.get(level, 'unknown')


class SessionToken:
    """Compact binary session token with HMAC integrity."""

    # Token format: [user_id:4][role:1][issued_at:4][flags:1][hmac:32]
    TOKEN_FORMAT = '>IBIb'
    HEADER_SIZE = struct.calcsize('>IBIb')  # 10 bytes

    @staticmethod
    def create(user_id: int, role_level: int, flags: int = 0) -> bytes:
        """Create a new session token."""
        if not (0 <= role_level <= MAX_ROLE_LEVEL):
            raise ValueError(f"Invalid role level: {role_level}")
        issued_at = int(time.time())
        header = struct.pack('>IBIb', user_id, role_level, issued_at, flags)
        mac = hmac.new(SECRET_KEY.encode(), header, hashlib.sha256).digest()
        return header + mac

    @staticmethod
    def parse(token: bytes) -> dict:
        """Parse and validate a session token."""
        if len(token) != SessionToken.HEADER_SIZE + 32:
            raise ValueError("Invalid token length")

        header = token[:SessionToken.HEADER_SIZE]
        provided_mac = token[SessionToken.HEADER_SIZE:]

        expected_mac = hmac.new(
            SECRET_KEY.encode(), header, hashlib.sha256
        ).digest()

        if not hmac.compare_digest(provided_mac, expected_mac):
            raise ValueError("Invalid token signature")

        user_id, role_level, issued_at, flags = struct.unpack(
            '>IBIb', header
        )

        # Validate role level is within expected bounds
        if role_level > MAX_ROLE_LEVEL:
            raise ValueError("Invalid role in token")

        return {
            'user_id': user_id,
            'role': role_level,
            'issued_at': issued_at,
            'flags': flags
        }


class PermissionCache:
    """Caches permission check results for performance."""

    def __init__(self, max_size=1024):
        self._cache = {}
        self._max_size = max_size

    def get_or_compute(self, user_role: int, required_level: int) -> bool:
        """Check if user_role has sufficient privileges."""
        cache_key = (user_role, required_level)
        if cache_key in self._cache:
            return self._cache[cache_key]

        result = self._compute_access(user_role, required_level)

        if len(self._cache) < self._max_size:
            self._cache[cache_key] = result

        return result

    def _compute_access(self, user_role: int, required_level: int) -> bool:
        """Core permission computation.

        Direct comparison: user's role level must meet or exceed
        the required level for the resource.
        """
        return user_role >= required_level


class AccessController:
    """Main access control entry point."""

    def __init__(self):
        self.hierarchy = RoleHierarchy()
        self.perm_cache = PermissionCache()
        self._audit_log = []

    def check_access(self, token: bytes, resource: str) -> dict:
        """Verify token and check resource access."""
        # Step 1: Validate and parse token
        try:
            session = SessionToken.parse(token)
        except ValueError as e:
            return {'allowed': False, 'reason': str(e)}

        # Step 2: Check session expiry
        now = int(time.time())
        if now - session['issued_at'] > SESSION_TIMEOUT:
            return {'allowed': False, 'reason': 'Session expired'}

        # Step 3: Check flags (bit 0 = account locked)
        if session['flags'] & 0x01:
            return {'allowed': False, 'reason': 'Account locked'}

        # Step 4: Get required level for resource
        required = self.hierarchy.get_required_level(resource)

        # Step 5: Check permission
        user_role = session['role']
        allowed = self.perm_cache.get_or_compute(user_role, required)

        # Step 6: Audit
        self._audit_log.append({
            'user_id': session['user_id'],
            'resource': resource,
            'role': self.hierarchy.role_name(user_role),
            'allowed': allowed,
            'timestamp': now
        })

        if allowed:
            return {'allowed': True, 'user_id': session['user_id']}
        else:
            return {
                'allowed': False,
                'reason': f"Insufficient privileges: "
                          f"{self.hierarchy.role_name(user_role)} "
                          f"cannot access {resource}"
            }


def handle_request(raw_token: bytes, path: str) -> dict:
    """HTTP request handler."""
    controller = AccessController()

    # Normalize path
    path = '/' + path.strip('/').lower()

    return controller.check_access(raw_token, path)
